-- Added for the explicitly requested automation acceptance scope; do not edit older migrations.
CREATE TABLE AgentPresence (MaUser INT PRIMARY KEY, LastSeen DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CONSTRAINT FK_Presence_User FOREIGN KEY(MaUser) REFERENCES UserAccount(MaUser)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE TicketAutomation (MaTicket INT PRIMARY KEY, State VARCHAR(20) NOT NULL DEFAULT 'Pending', Category VARCHAR(100) NOT NULL DEFAULT 'Cần kiểm tra', Priority VARCHAR(30) NULL, Sentiment VARCHAR(30) NULL, UpdatedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CONSTRAINT FK_Automation_Ticket FOREIGN KEY(MaTicket) REFERENCES Ticket(MaTicket), CONSTRAINT CK_TicketAutomation_State CHECK(State IN ('Pending','Done','Failed','Stale'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE MessageAutomation (MaMessage INT PRIMARY KEY, State VARCHAR(20) NOT NULL DEFAULT 'Pending', Sentiment VARCHAR(30) NULL, UpdatedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CONSTRAINT FK_Automation_Message FOREIGN KEY(MaMessage) REFERENCES Message(MaMessage), CONSTRAINT CK_MessageAutomation_State CHECK(State IN ('Pending','Done','Failed'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE SupervisorAlert (MaAlert BIGINT AUTO_INCREMENT PRIMARY KEY, SourceType VARCHAR(20) NOT NULL, SourceId INT NOT NULL, Sentiment VARCHAR(30) NOT NULL, CreatedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), AcknowledgedBy INT NULL, AcknowledgedAt DATETIME(3) NULL, CONSTRAINT UQ_Alert_Source UNIQUE(SourceType,SourceId), CONSTRAINT FK_Alert_Actor FOREIGN KEY(AcknowledgedBy) REFERENCES UserAccount(MaUser)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE SentimentAnalysis DROP CHECK CK_Sentiment_Label, ADD CONSTRAINT CK_Sentiment_Label CHECK(CamXuc IN ('Tích cực','Trung tính','Tiêu cực','Bức xúc cao'));
ALTER TABLE TicketAIAnalysis DROP CHECK CK_TicketAI_Sentiment, ADD CONSTRAINT CK_TicketAI_Sentiment CHECK(SentimentSuggestion IN ('Tích cực','Trung tính','Tiêu cực','Bức xúc cao'));
INSERT INTO TicketCategory(TenCategory,MoTa) SELECT 'Cần kiểm tra','Hàng chờ chung khi AI chưa phân loại được' WHERE NOT EXISTS (SELECT 1 FROM TicketCategory WHERE TenCategory='Cần kiểm tra');
